    applyGlow(this.ctx, '#39ff14', 20);
    this.ctx.globalAlpha = 0.4;
    this.ctx.fillText(text, centreX, centreY);
    clearGlow(this.ctx);
    this.ctx.globalAlpha = 1.0;
  }

  /**
   * Call when canvas is resized (via ResizeObserver)
   */
  onResize(): void {
    this.resizeCanvas();
  }
}

