  channelRow: {
    display: 'flex',
    gap: '8px',
    alignItems: 'center',
  },
  channelLabel: {
    display: 'flex',
    gap: '6px',
    alignItems: 'center',
    cursor: 'pointer',
    minHeight: '44px',
    minWidth: '44px',
  },
  channelCheckbox: {
    cursor: 'pointer',
    accentColor: '#39ff14',
  },
  channelSwatch: {
    display: 'inline-block',
    width: '12px',
