            <div className="examples-list">
              {EXAMPLE_CIRCUITS.map((ex) => (
                <button
                  key={ex.id}
                  className={`example-button ${selectedExampleId === ex.id ? 'active' : ''}`}
                  onClick={() => handleLoadExample(ex.id)}
