      }
    }
    this.ctx.stroke();
  }

  private drawNoSignal(locale: Record<string, string>): void {
    const { canvasWidth, canvasHeight } = this.getCanvasDimensions();
    const centreX = canvasWidth / 2;
    const centreY = canvasHeight / 2;

    // Text
    this.ctx.fillStyle = '#39ff14';
