    for (let i = 0; i < decimated.length; i++) {
      const { t, v } = decimated[i];
      const x = centreX + t * pixelsPerX;
      const y = centreY - v * pixelsPerY;
      if (i === 0) {
        this.ctx.moveTo(x, y);
      } else {
        this.ctx.lineTo(x, y);
      }
    }
