  private drawTraces(
    viewState: ScopeViewState,
    simResult: SimResult,
    metrics: ScopeMetrics,
    _timestamp: number
  ): void {
    if (viewState.analysisType !== 'tran') {
      return; // Only transient for now
    }

    const timeData = simResult.data[0]?.values as number[] | undefined;
