    this.ctx.strokeStyle = 'rgba(57, 255, 20, 0.3)';
    this.ctx.lineWidth = 1;
    this.ctx.beginPath();
    this.ctx.moveTo(centreX - 10, centreY);
    this.ctx.lineTo(centreX + 10, centreY);
    this.ctx.stroke();
    this.ctx.beginPath();
    this.ctx.moveTo(centreX, centreY - 10);
    this.ctx.lineTo(centreX, centreY + 10);
    this.ctx.stroke();

