      pixelsPerDiv,
      voltsPerPx: viewState.voltsPerDiv / pixelsPerDiv,
      timePerPx: viewState.timePerDiv / pixelsPerDiv,
      centreX: canvasWidth / 2,
      centreY: canvasHeight / 2,
      canvasWidth,
      canvasHeight,
