import { ScopeCanvas, ScopeControls, type ScopeViewState } from '@/features/scope';
import { EXAMPLE_CIRCUITS } from '@/examples';
import './app.css';

export default function App() {
  const [settings, setSettings] = useState<AppSettings>({
    llm: null,
